"""Prospective numerical checks. These are diagnostics, not a training reward."""

from __future__ import annotations

import math
from statistics import mean

from .measurements import finite

_STAGE_ALIASES = {
    "as_sintered": "as_sintered",
    "initial_sps": "as_sintered",
    "as_sps": "as_sintered",
    "as-sps": "as_sintered",
    "as-sintered": "as_sintered",
    "as sintered": "as_sintered",
    "after_first_anneal": "after_first_anneal",
    "after_second_anneal": "after_second_anneal",
}
_UNKNOWN_STAGES = {"", "unknown", "unresolved", "unspecified", "not_recorded", "none"}
_AMBIGUOUS_STAGES = {
    "annealed", "post_anneal", "post-anneal", "post_sinter_anneal", "post_annealing",
    "post_sinter_annealing", "postanneal", "as_annealed",
}
NUMERICAL_QUANTITIES = (
    "density_g_cm3", "grain_size_nm", "grain_d90_nm", "coarse_number_fraction",
    "porosity_area_fraction",
)
ABSTENTION_STATUSES = {"unsupported", "unavailable", "abstained"}


def measurement_definition_check(item, observation, *, specimen=None):
    """Match explicit frozen measurement definitions, without interpreting model code.

    No definition is inferred from a computational ``method`` or narrative scope.
    Equivalent experimental definitions must be normalized before commitment with
    provenance; numerical-model representations are deliberately irrelevant here.
    Absent legacy definitions remain visibly unverified, not silently validated.
    """
    item, specimen = item or {}, specimen or {}
    applicability = item.get("applicability") or {}
    if not isinstance(applicability, dict):
        applicability = {}
    contexts = specimen.get("conditions", {}).get("measurement_context", {})
    if not isinstance(contexts, dict):
        contexts = {}
    quantity = observation.get("quantity")
    scopes = [
        ("forecast.quantity.measurement_context", item.get("measurement_context")),
        ("forecast.quantity.applicability.measurement_context",
         applicability.get("measurement_context")),
        ("request.specimen.conditions.measurement_context", contexts.get(quantity)),
    ]
    checks = []
    for key in ("method", "measurement_population", "measurement_statistic",
                "feature_definition", "weighting", "sampling_plan", "statistical_unit"):
        for label, scope in scopes:
            if isinstance(scope, dict) and key in scope:
                expected, actual = scope[key], observation.get(key)
                status = "matched" if expected is not None and expected == actual else (
                    "not_assessable" if expected is None or actual is None else "incompatible"
                )
                checks.append({"field": key, "expected": expected, "observed": actual,
                               "expected_source": f"{label}.{key}", "status": status})
                break
    reason = None
    if any(check["status"] == "incompatible" for check in checks):
        reason = "measurement_definition_mismatch"
    elif any(check["status"] == "not_assessable" for check in checks):
        reason = "measurement_definition_unknown"
    return {"checks": checks, "reason": reason,
            "status": "not_declared" if not checks else (
                "matched" if reason is None else "not_assessable"
                if reason.endswith("unknown") else "incompatible"
            )}


def _stage_at(scopes, *, forecast=False):
    """Read an explicit endpoint, without interpreting prose or filling readbacks."""
    for label, scope in scopes:
        if not isinstance(scope, dict):
            continue
        keys = ("measurement_stage", "forecast_stage", "process_stage", "stage") if forecast else (
            "measurement_stage", "process_stage"
        )
        for key in keys:
            if key not in scope:
                continue
            value = scope[key]
            stage = value.strip() if isinstance(value, str) else None
            normalized = stage.lower() if stage is not None else None
            # Dated immutable requests used stage='as-sintered'. Accept only
            # established endpoint vocabulary here; do not interpret arbitrary
            # generic stage labels or promote a forecast label to actual history.
            if key == "stage" and normalized not in _STAGE_ALIASES:
                continue
            if normalized in _UNKNOWN_STAGES:
                stage = None
            elif normalized in _AMBIGUOUS_STAGES:
                stage = normalized
            else:
                stage = _STAGE_ALIASES.get(normalized, stage)
            return stage, f"{label}.{key}"
    return None, None


def measurement_stage_check(item, observation, *, forecast=None, specimen=None):
    """Check the committed endpoint against reported measurement history.

    A specimen's manufacturing stage is not a substitute for a later measurement
    endpoint. Explicit quantity/observation measurement_stage takes precedence.
    Legacy stage-free synthetic diagnostics are retained with an explicit warning;
    physical or unspecified-origin observations never receive that exception.
    """
    item, forecast, specimen = item or {}, forecast or {}, specimen or {}
    applicability = item.get("applicability")
    if not isinstance(applicability, dict):
        applicability = {}
    expected, expected_source = _stage_at([
        ("forecast.quantity", item),
        ("forecast.quantity.applicability.requested", applicability.get("requested")),
        ("forecast", forecast),
        ("request.specimen", specimen),
        ("request.specimen.conditions", specimen.get("conditions")),
    ], forecast=True)
    actual, actual_source = _stage_at([
        ("observation", observation),
        ("observation.delivered_conditions", observation.get("delivered_conditions")),
    ])
    reason = None
    if expected is None and actual is None and observation.get("origin") == "synthetic":
        status = "legacy_synthetic_stage_unverified"
    elif expected is None:
        status, reason = "not_assessable", "forecast_measurement_stage_unknown"
    elif actual is None:
        status, reason = "not_assessable", "observation_measurement_stage_unknown"
    elif expected in _AMBIGUOUS_STAGES or actual in _AMBIGUOUS_STAGES:
        status, reason = "not_assessable", "measurement_stage_ambiguous"
    elif expected != actual:
        status, reason = "incompatible", "measurement_stage_mismatch"
    else:
        status = "matched"
    return {
        "expected": expected, "observed": actual,
        "expected_source": expected_source, "observed_source": actual_source,
        "status": status, "reason": reason,
    }


def quality_review_exclusion(observation):
    review = observation.get("quality_review")
    if review is None and observation.get("status") != "derived":
        return None
    if isinstance(review, dict) and review.get("decision") == "rejected":
        return "measurement excluded by explicit quality rejection"
    if not (isinstance(review, dict) and review.get("decision") == "accepted"
            and all(isinstance(review.get(k), str) and review[k].strip()
                    for k in ("reviewer", "rationale"))):
        return "measurement lacks accepted quality review"
    return None


def evaluate_predictions(prediction, observations, *, request=None):
    """Match saved specimen forecasts to released observations without imputation.

    This is a descriptive lower-level API, not a freshness verifier. Use
    scientific_checks.evaluate_campaign_request with a complete immutable request
    record for prospective evaluation (including the public CLI).

    Caller supplies the immutable pre-execution prediction, not a later delivered-
    condition calculation. Correlated fields/sections remain individual residuals,
    never independently manufactured replicate counts. No p-values are inferred.
    """
    forecasts = prediction.get("predictions", [])
    if not isinstance(forecasts, list):
        raise TypeError("prediction.predictions must be a list")
    by_specimen = {}
    for forecast in forecasts:
        sid = forecast["specimen_id"]
        if sid in by_specimen:
            raise ValueError("duplicate forecast specimen")
        by_specimen[sid] = forecast
    specimens = {s["specimen_id"]: s for s in (request or {}).get("specimens", [])}
    residuals, skipped, stage_checks, definition_checks = [], [], [], []
    seen_evidence, seen_measurements = set(), set()
    for obs in observations:
        quantity = obs.get("quantity")
        sid = obs.get("specimen_id")
        item = by_specimen.get(sid, {}).get(quantity)
        if item is not None and not isinstance(item, dict):
            raise TypeError("forecast quantity must be an object")
        stage = measurement_stage_check(
            item, obs, forecast=by_specimen.get(sid), specimen=specimens.get(sid)
        )
        stage_checks.append({"evidence_id": obs.get("evidence_id"), "specimen_id": sid,
                             "quantity": quantity, **stage})
        definition = measurement_definition_check(item, obs, specimen=specimens.get(sid))
        definition_checks.append({"evidence_id": obs.get("evidence_id"), "specimen_id": sid,
                                  "quantity": quantity, **definition})
        eid = obs.get("evidence_id")
        if item is not None and isinstance(eid, str) and eid:
            if eid in seen_evidence:
                raise ValueError("duplicate target evidence_id; resolve identity before scoring")
            seen_evidence.add(eid)
        reason = None
        if obs.get("superseded"):
            reason = "superseded observation"
        elif quality_review_exclusion(obs):
            reason = quality_review_exclusion(obs)
        elif obs.get("status") in {"invalid", "rejected", "missing", "unresolved", "unavailable"}:
            reason = "measurement excluded by quality status"
        elif quantity in {"grain_size_nm", "grain_d90_nm", "coarse_number_fraction"} and obs.get("resolved_grain_boundaries") is not True:
            reason = "grain boundary resolution not established"
        elif item is None:
            reason = "no matching prospective forecast"
        elif obs.get("value") is None:
            reason = "measurement unavailable"
        elif item.get("mean") is None:
            if item.get("sd") is not None:
                raise ValueError("forecast abstention cannot carry numerical uncertainty")
            reason = "forecast abstention"
        elif item.get("status") in ABSTENTION_STATUSES:
            raise ValueError("numeric forecast contradicts its abstention status")
        elif item.get("unit") != obs.get("unit"):
            raise ValueError(f"unit mismatch for {sid}/{quantity}")
        elif quantity == "coarse_number_fraction" and (
            item.get("coarse_threshold_nm") is None
            or item.get("coarse_threshold_nm") != obs.get("coarse_threshold_nm")
        ):
            reason = "coarse threshold differs or is unspecified"
        elif stage["reason"]:
            reason = stage["reason"]
        elif definition["reason"]:
            reason = definition["reason"]
        if reason:
            skipped.append({"specimen_id": sid, "quantity": quantity, "reason": reason,
                            "evidence_id": obs.get("evidence_id"), "measurement_stage": stage})
            continue
        # Distinct evidence labels do not make a repeated identified measurement
        # independent. Explicit repeat/measurement IDs permit genuine repeated
        # readings; otherwise the same field/section/endpoint is one identity.
        measurement_id = (obs.get("measurement_id") or obs.get("repeat_id")
                          or obs.get("observation_id"))
        field_id = obs.get("field_id")
        if measurement_id is not None or field_id is not None:
            identity = (obs.get("request_id"), sid, quantity, stage["observed"],
                        obs.get("section_id"), field_id, measurement_id)
            if identity in seen_measurements:
                raise ValueError("duplicate reported measurement identity; resolve before scoring")
            seen_measurements.add(identity)
        predicted = finite(item["mean"], "forecast mean")
        observed = finite(obs["value"], "observation")
        sd = item.get("sd")
        if sd is not None:
            sd = finite(sd, "forecast standard deviation", nonnegative=True)
        error = predicted - observed
        row = {
            "specimen_id": sid,
            "quantity": quantity,
            "unit": item["unit"],
            "predicted": predicted,
            "observed": observed,
            "error": error,
            "forecast_sd": sd,
            "evidence_id": obs.get("evidence_id"),
            "origin": obs.get("origin"),
            "request_id": obs.get("request_id"),
            "measurement_stage": stage["observed"],
            "measurement_stage_status": stage["status"],
            "interval_contains_observation": None,
            "nominal_95_interval_width": None,
            "normal_95_interval_score": None,
            "normal_nll": None,
            "uncertainty_diagnostic_status": "not_estimated" if sd is None else (
                "degenerate_zero_sd" if sd == 0 else "conditional_gaussian"
            ),
        }
        if sd is not None and sd > 0:
            # Conditional Gaussian diagnostic only; does not assert physical calibration.
            radius = 1.959963984540054 * sd
            row["interval_contains_observation"] = abs(error) <= radius
            row["nominal_95_interval_width"] = 2 * radius
            row["normal_95_interval_score"] = 2 * radius + 40 * max(abs(error) - radius, 0)
            row["normal_nll"] = math.log(sd) + 0.5 * math.log(2 * math.pi) + 0.5 * (error / sd) ** 2
            for key in ("nominal_95_interval_width", "normal_95_interval_score", "normal_nll"):
                finite(row[key], key)
        residuals.append(row)
    summaries = {}
    for quantity in sorted({row["quantity"] for row in residuals}):
        rows = [row for row in residuals if row["quantity"] == quantity]
        intervals = [
            row["interval_contains_observation"]
            for row in rows
            if row["interval_contains_observation"] is not None
        ]
        summaries[quantity] = {
            "observation_count": len(rows),
            "distinct_specimens": len({row["specimen_id"] for row in rows}),
            "mae": mean(abs(row["error"]) for row in rows),
            "rmse": math.sqrt(mean(row["error"] ** 2 for row in rows)),
            "nominal_95_interval_coverage": mean(intervals) if intervals else None,
            "interval_count": len(intervals),
            "mean_normal_nll": mean(row["normal_nll"] for row in rows
                                    if row["normal_nll"] is not None) if intervals else None,
            "mean_nominal_95_interval_width": mean(row["nominal_95_interval_width"] for row in rows
                                                  if row["normal_nll"] is not None) if intervals else None,
            "mean_normal_95_interval_score": mean(row["normal_95_interval_score"] for row in rows
                                                 if row["normal_nll"] is not None) if intervals else None,
        }
    return {
        "evaluation_scope": "descriptive_matched_observations",
        "freshness_verified": False,
        "residuals": residuals,
        "summaries": summaries,
        "skipped": skipped,
        "measurement_stage_checks": stage_checks,
        "measurement_definition_checks": definition_checks,
        "limits": [
            "Descriptive matched-observation diagnostics, not process equivalence",
            "Specimens can share powder preparation, process cycle and lot effects",
            "Gaussian interval diagnostics inherit the forecast uncertainty assumptions",
            "Interval coverage alone rewards inflated uncertainty; inspect width and proper scores",
            "Undeclared measurement definitions are unverified, not assumed comparable",
            "Source fits and synthetic outcomes do not validate a physical twin",
            "Stage matching does not verify measurement method, population or physical history",
            "Stage-free legacy synthetic diagnostics remain stage-unverified",
            "No agent advantage, magnetic benefit or learning transfer inferred",
        ],
    }
